return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Turkish','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 20:18+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'tr_TR','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'WordPress için çok dilli yönlendirme, SEO meta etiketleri ve AI içerik araçları. Dil tespiti, URL yönlendirmesi, hreflang, meta açıklamaları ve AI destekli alıntı, meta ve çeviri özelliklerini birleştirir.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Çevir','Lingua Forge — Quick Translate'=>'Lingua Forge — Hızlı Çeviri','Informative'=>'Bilgilendirici','Persuasive'=>'İkna edici','Storytelling'=>'Hikaye Anlatımı','Technical'=>'Teknik','Conversational'=>'Konuşma Dili','Permission denied.'=>'İzin reddedildi.','Cannot determine target language from slug.'=>'Hedef dili slug\'dan belirlenemiyor.','Invalid post type.'=>'Geçersiz gönderi türü.','Invalid or primary language.'=>'Geçersiz veya ana dil.','Template not found or not stored in the database.'=>'Şablon bulunamadı veya veritabanında saklanmadı.','Template has no content.'=>'Şablonun içeriği yok.','No internal links found to update.'=>'Güncellenecek dahili bağlantı bulunamadı.','%d link updated.'=>'%d bağlantı güncellendi.' . "\0" . '%d bağlantı güncellendi.','No language-specific template parts found to map.'=>'Haritalanacak dil\'e özgü şablon parçası bulunamadı.','No template part references needed updating.'=>'Güncellenecek şablon parçası referansı yok.','%d part reference updated.'=>'%d parça referansı güncellendi.' . "\0" . '%d parça referansı güncellendi.','Invalid language.'=>'Geçersiz dil.','Template part not found or not stored in the database.'=>'Şablon parçası bulunamadı veya veritabanında saklanmadı.','Template part has no content.'=>'Şablon parçasının içeriği yok.','No navigation references needed updating.'=>'Güncellenecek gezinme referansı yok.','%d navigation reference updated.'=>'%d gezinme referansı güncellendi.' . "\0" . '%d gezinme referansı güncellendi.','No AI provider configured.'=>'AI sağlayıcısı yapılandırılmadı.','Missing pattern name or language.'=>'Desen adı veya dil eksik.','Pattern not found.'=>'Desen bulunamadı.','Pattern has no content to translate.'=>'Desenin çevrilecek içeriği yok.','AI provider returned an empty response.'=>'AI sağlayıcısı boş yanıt döndürdü.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Desen çevrildi ve kaydedildi. İçeriği blok düzenleyici Desen ekleyicisi aracılığıyla CPT gönderinize yapıştırın veya Yeniden Kullanılabilir Blok için başlangıç noktası olarak kullanın.','Invalid template type.'=>'Geçersiz şablon türü.','Template "%s" already exists.'=>'"%s" zaten var.','"%s" created.'=>'"%s" oluşturuldu.','Invalid template part.'=>'Geçersiz şablon parçası.','Template part "%s" already exists.'=>'"%s" şablon parçası zaten var.','"%1$s" created. %2$d template updated.'=>'"%1$s" oluşturuldu. %2$d şablon güncellendi.' . "\0" . '"%1$s" oluşturuldu. %2$d şablon güncellendi.','Page'=>'Sayfa','Single'=>'Tek','Search'=>'Arama','Search Results'=>'Arama Sonuçları','Archive'=>'Arşiv','Front Page'=>'Ana Sayfa','Single: %s'=>'Tek: %s','Single %s'=>'Tek %s','Archive: %s'=>'Arşiv: %s','%s Archive'=>'%s Arşivi','No source content found to translate.'=>'Çeviri yapılacak kaynak içerik bulunamadı.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Çevirildi. Site Düzenleyici\'de inceleyin — dahili bağlantılar, gezinme URL\'leri ve şablon slug\'ları otomatik olarak güncellenmez.','Navigation not found.'=>'Gezinme bulunamadı.','Navigation has no content to translate.'=>'Gezinmenin çevrilecek içeriği yok.','"%1$s %2$s" saved.'=>'"%1$s %2$s" kaydedildi.','Translate page…'=>'Sayfayı çevir…','Generate content…'=>'İçerik oluştur…','AI Behaviour Preset'=>'Yapay Zeka Davranış Ön Ayarı','Custom'=>'Özel','Global default (%s)'=>'Global varsayılan (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Bu sayfadaki Çeviri ve İçerik Oluşturma için Yapay Zeka ön ayarını geçersiz kılar. Site genelinde özel istem talimatları (Ayarlar → Davranış) her isteğe eklenir, bu seçimden bağımsızdır.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Bu sayfadaki Çeviri ve İçerik Oluşturma için Yapay Zeka ön ayarını geçersiz kılar. Diğer tüm özellikler her zaman küresel ön ayarı kullanır.','Close'=>'Kapat','Translate missing'=>'Eksik çeviriyi çevir','From'=>'İle','Retranslate'=>'Yeniden çevir','Translating…'=>'Çeviriliyor…','Retranslating…'=>'Yeniden çeviriliyor…','✓ Done'=>'✓ Tamamlandı','Error'=>'Hata','Navigation posts are translated via the Router tab, not this button.'=>'Gezinme gönderileri, bu düğme yerine Router sekmesi aracılığıyla çevrilir.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'"%s" gönderi türü için çeviri oluşturmak, aktif bir entegrasyon gerektirir. Lütfen gerekli entegrasyonun yüklü ve aktif olduğundan emin olun.','No %s version found in this translation group.'=>'Bu çeviri grubunda %s sürümü bulunamadı.','AI Usage'=>'Yapay Zeka Kullanımı','Today'=>'Bugün','Last 7 days'=>'Son 7 gün','Last 30 days'=>'Son 30 gün','All time'=>'Tüm zamanlar','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Token tüketimi özellik, sağlayıcı ve model bazında toplanır. Her başarılı Yapay Zeka çağrısında kaydedilir; Test Bağlantısı pingsleri kasıtlı olarak hariç tutulur, böylece toplamlar sapmaz. Temel tablo günlük olarak özetlenir — görmek için aşağıdaki pencereden seçim yapın.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Henüz Yapay Zeka kullanımı kaydedilmedi. Bir editör çeviri yaparsa, meta açıklaması oluşturursa veya başka bir Yapay Zeka özelliği kullanırsa, toplamlar burada görünecek.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Seçilen pencerede Yapay Zeka kullanımı kaydı yok (%s). Yukarıdaki daha geniş bir aralık seçin.','Feature'=>'Özellik','Provider'=>'Sağlayıcı','Model'=>'Model','Requests'=>'İstekler','Input tokens'=>'Girdi tokenleri','Output tokens'=>'Çıktı tokenleri','Total tokens'=>'Toplam tokenler','Total'=>'Toplam','API Keys'=>'API Anahtarları','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Anahtarlar, WordPress veritabanında saklanmadan önce AES-256-CBC ile şifrelenir. Şifreleme sırrı, WordPress kimlik doğrulama tuzlarınızdan (wp-config.php) türetilir, bu nedenle düz metin anahtarlar asla veritabanına dokunmaz.','API Key'=>'API Anahtarı','Paste your API key…'=>'API anahtarınızı yapıştırın…','✓ Configured'=>'✓ Yapılandırıldı','✗ Not configured'=>'✗ Yapılandırılmadı','Test connection'=>'Bağlantıyı test et','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Boş bırakmak mevcut anahtarı korur. Yenisini girerek değiştirebilirsiniz.','Remove stored key'=>'Depolanan anahtarı kaldır','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Bu anahtar şu anda bir sunucu %s tarafından sağlanmaktadır ve burada kaldırılamaz. Üzerine yeni bir anahtar girerek veritabanı değeriyle üzerine yazabilirsiniz.','environment variable'=>'ortam değişkeni','PHP constant'=>'PHP sabiti','Alternative (server-side):'=>'Alternatif (sunucu tarafı):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Anahtarları sabitler veya ortam değişkenleri olarak da tanımlayabilirsiniz (örneğin wp-config.php\'de). Bu kaynaklar, veritabanı anahtarı depolanmadığında otomatik olarak yedek olarak kullanılır.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Kullanıcı tarafından belirlenen şifreleme sırrını kullanmak için (türetilmiş wp_salt değili yerine), bunu wp-config.php\'ye ekleyin:','Unknown provider.'=>'Bilinmeyen sağlayıcı.','No API key configured for this provider.'=>'Bu sağlayıcı için yapılandırılmış API anahtarı yok.','Could not instantiate the provider.'=>'Sağlayıcı başlatılamadı.','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Sağlayıcı herhangi bir metin döndürmedi. Ayrıntılı başarısızlık nedenini WordPress hata günlüğünde kontrol edin.','Behavior'=>'Davranış','Block Editor'=>'Blok Düzeni','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge, dil genelinde düzenleyici davranışı tutarlı tutmak için varsayılan olarak iki Gutenberg özelliğini sınırlar. Tam Gutenberg / FSE yeteneklerine ihtiyacınız olduğunda buradan katılın.','Block locking'=>'Blok kilitleme','Allow editors to lock individual blocks'=>'Editörlerin bireysel blokları kilitlemesine izin ver','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Gutenberg\'in canLockBlocks özelliğini yeniden etkinleştirir. Katkıda bulunanların belirli blokları taşımalarını veya silmelerini engellemesi gereken düzenleyici şablonlar için kullanışlıdır.','Template mode'=>'Şablon modu','Allow Gutenberg template-editing mode on post screens'=>'Yazı ekranlarında Gutenberg şablon düzenleme moduna izin ver','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'supportsTemplateMode\'u yeniden etkinleştirir. Yazı seviyesi şablon geçersiz kılmalarının kasıtlı olduğu Tam Site Düzenleme iş akışlarının temelidir.','Compliance Preset'=>'Uyumluluk Ön Ayarı','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Yasal, düzenleyici, tıbbi veya teknik içerik için katı koruma modu. Açık olduğunda, her yapay zeka özelliği düşük örnekleme sıcaklığı kullanır ve sistem istemine aşağıdaki ek açıklamayı ekler — terminoloji, makale numaraları, birimler, marka isimleri ve düzenleyici dil kelimesi kelimesine korunur, paraphrase edilmez.','Global AI preset'=>'Küresel Yapay Zeka ön ayarı','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, özellik başına','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Tüm site genelinde varsayılan yapay zeka davranışını ayarlar. Bireysel yazılar, Lingua Forge meta kutusu aracılığıyla Çeviri ve İçerik Oluşturma için bunu geçersiz kılabilir.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standart, her özelliğin kendi ayarlanmış sıcaklığını kullanır: Çeviri T=0.2 (kesin), Hızlı Çeviri T=0.4, İçerik Üretici T=0.6 (yaratıcı). Diğer ön ayarlar, tüm özelliklerde tek bir sabit sıcaklık uygular.','Technical / Scientific instructions'=>'Teknik / Bilimsel talimatlar','Legal / Compliance instructions'=>'Yasal / Uyumluluk talimatları','Creative / Marketing instructions'=>'Yaratıcı / Pazarlama talimatları','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Varsayılanı kullanmak için boş bırakın. Kaydedilen bir geçersiz kılmayı temizlemek, varsayılanı bir sonraki kayıtta geri yükler.','View built-in default'=>'Yerleşik varsayılanı görüntüle','Translation Memory'=>'Çeviri Belleği','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Yeniden kullanılabilir içeriklerin (paylaşılan altbilgiler, kenar çubukları, akordiyonlar, standart hukuk bölümleri) API çağrısı yapmadan önce önbelleğe alınmasını sağlar. Etkinleştirildiğinde, çeviri akışı her yazıyı bloklara ayırır, her bloğu önbellekte arar ve yalnızca önbelleğe alınmamış blokları tek bir toplu istekle yapay zekaya gönderir. Terim sözlüğü düzenlemeleri ve Uyumluluk ön ayarı değişiklikleri otomatik olarak etkilenen önbelleğe alınmış çevirileri geçersiz kılar. İstatistikleri görüntüle ve önbelleği temizle.','Enable block-level translation cache reuse across posts'=>'Blok seviyesinde çeviri önbelleği yeniden kullanımını etkinleştir','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Şu anda, blok-yorum öznitelik yer tutucuları (wp:details özet alanları vb.) kullanan yazılar için atlanır — bunlar mevcut tek çağrı çeviri yoluna geçer.','General'=>'Genel','Light'=>'Hafif','Meta Description, Excerpt Generator'=>'Meta Açıklaması, Alıntı Üretici','Quality'=>'Kalite','Translation, Content Generator'=>'Çeviri, İçerik Üretici','Active Provider'=>'Aktif Sağlayıcı','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Şu anda %s sabitinden miras alınmıştır. Buraya bir değer seçmek, onu geçersiz kılar.','Models'=>'Modeller','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Özellikler iki seviyeye ayrılmıştır. Her seviye ve sağlayıcı için tam model tanımlayıcısını girin. Yer tutucu olarak gösterilen yerleri boş bırakın. Yalnızca aktif sağlayıcının modelleri çalışma zamanında çağrılır — diğerlerini önceden yapılandırın, eğer değiştirmeyi planlıyorsanız.','active'=>'aktif','overridden'=>'geçersiz kılındı','Tip: to reset a model to the built-in default, clear the field and save.'=>'İpucu: Bir modeli yerleşik varsayına sıfırlamak için alanı temizleyin ve kaydedin.','Glossary'=>'Terim Sözlüğü','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Dil çifti başına kullanıcı tarafından yönetilen terim tablosu. Girişler, AI\'nın tercih edilen terimleri tutarlı şekilde kullanması için çeviri sisteminin istemine eklenir — alan kelime dağarcığı ("kWp", "PPA", "bağlantı noktası"), değiştirilmemesi gereken marka isimleri ve standartlaştırılmış düzenleyici ifadeler için kritik önemdedir. Her iki dil alanı da isteğe bağlıdır: "Kaynak dili" boş bırakın, böylece giriş hangi dilden çeviri yapılıyor olursa olsun uygulanır; "Hedef dili" boş bırakın, böylece tüm hedef dillere aynı anda uygulanır.','Glossary entry added.'=>'Terimlik girişi eklendi.','Glossary entry removed.'=>'Terimlik girişi kaldırıldı.','Could not add entry: source term and target term are required.'=>'Giriş eklenemedi: kaynak terim ve hedef terim gereklidir.','Could not save the glossary entry.'=>'Terimlik giriş kaydedilemedi.','Source language'=>'Kaynak dili','— Any —'=>'— Herhangi —','Target language'=>'Hedef dil','— Any target —'=>'— Herhangi hedef —','Filter'=>'Filtre','Reset'=>'Sıfırla','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Mevcut filtreyle eşleşen terimlik girişi yok. Tüm girişleri görmek için filtreyi temizleyin veya aşağıda yeni bir giriş ekleyin.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Henüz terimlik girişi yok. Çevirilerde terimlerin uygulanmaya başlaması için aşağıda bir tane ekleyin.','Source term'=>'Kaynak terim','Target term'=>'Hedef terim','Source lang'=>'Kaynak dil','Target lang'=>'Hedef dil','Notes'=>'Notlar','any'=>'herhangi','Delete this glossary entry?'=>'Bu terimlik giriş silinsin mi?','Delete'=>'Sil','Add new entry'=>'Yeni giriş ekle','The phrase as it appears in the source text.'=>'Kaynak metinde göründüğü şekliyle ifade.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Çeviride nasıl görünmesi gerektiği. Aynı değeri kaynak terimle girin, böylece AI\'nin aynen korumasını sağlayın.','— Any source language —'=>'— Herhangi kaynak dili —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Marka isimleri ve dilden bağımsız terimler için boş bırakın, bunlar hangi dilden çeviri yapılıyor olursa olsun zorunludur.','— Any target language —'=>'— Herhangi hedef dili —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Bu girdiyi tüm hedef dillere uygulamak için boş bırakın — marka isimleri, kısaltmalar ve her çeviride aynen korunması gereken terimler için idealdir.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Editörler için isteğe bağlı bağlam (ör. "ASIC = Uygulamaya Özgü Entegre Devre; teknik bağlamlarda İngilizce korunmalı").','Add entry'=>'Giriş ekle','Limits'=>'Sınırlar','Authors and above (edit_published_posts)'=>'Yazarlar ve üzeri (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Katkıda bulunanlar ve üzeri — varsayılan (edit_posts)','Editors and above (edit_others_posts)'=>'Editörler ve üzeri (edit_others_posts)','Administrators only (manage_options)'=>'Yöneticiler sadece (manage_options)','AI Limits & Security'=>'AI Sınırları ve Güvenlik','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Site\'nin ne kadar AI kullanımı yapabileceğini sınırla ve hangi kullanıcı rollerinin ücretli AI çağrılarını tetikleyebileceğini kısıtla. Bu, zaten tek kullanıcı kaçak döngülerine karşı koruyan kullanıcı başına oran sınırının (30 istek / dakika, sabit kodlu) üzerine oturur.','Daily request limit'=>'Günlük istek sınırı','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'UTC günü başına site genelinde AI istekleri tavanı (Hem Araç Çubuğu çevirileri hem de blok revizyonlarını sayar). Sayacı UTC gece yarısı sıfırlar. Devre dışı bırakmak için 0 olarak ayarlayın.','Minimum role'=>'En düşük rol','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'AI özelliklerini tetiklemek için izin verilen en düşük WordPress yeteneği. Çok yazarlı sitelerde bunu sıkılaştırmak, Katkıda Bulunanlar veya deneme hesaplarının ücretli AI çağrılarını çalıştırmasını engeller. Özellik başına override etmek için linguaforge_required_capability filtresini kullanın.','Translation Limits'=>'Çeviri Sınırları','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'AI\'ye gönderilen içerik miktarını ve yanıtın ne kadar büyük olabileceğini kontrol et. Bir alanı boş bırakmak yerleşik varsayılanı kullanır (yer tutucu olarak gösterilir). Büyük sayfalar kesiliyorsa bu değerleri artırın; API maliyetlerini azaltmak için düşürün.','Model tier'=>'Model seviyesi','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Kalite (varsayılan — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Hafif (hızlı ve maliyet etkin — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Tam sayfa çeviri için kullanılacak model seviyesi. Kalite, yukarıdaki Modeller tablosunda yapılandırılan modeli kullanır ve doğru, uzun biçimli çeviri için önerilir. Sadece hız veya maliyet öncelikliyse ve içerik kısa ise Hafif\'e geçin.','Max output tokens'=>'Maksimum çıktı token sayısı','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'AI\'nin tek bir çeviri yanıtında üretebileceği maksimum token sayısı. Bir çeviri sessizce kesilirse, bu değeri artırın. Varsayılan: 16.000.','Max input characters'=>'Maksimum giriş karakterleri','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'AI\'ye iletilen gönderi içeriğinin maksimum karakter sayısı. 0 ise sınır yok — tam içerik her zaman gönderilir (önerilir). Sağlayıcınızın sıkı bir bağlam penceresi varsa, sıfır olmayan bir değer ayarlayın. İçerik kısaltıldığında PHP hata günlüğüne uyarı yazılır.','Quick Translation'=>'Hızlı Çeviri','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Hızlı Çeviri, snippet/parça modu için kullanılır — araç çubuğu, düzenleyici veya blok açılır pencerelerinden talep üzerine kısa pasajlar çevrilir. Yanıtları hızlı ve maliyet etkin tutmak için tam sayfa çeviriden ayrı, daha hafif bir yapılandırma kullanır.','Light (default — fast and cost-effective)'=>'Hafif (varsayılan — hızlı ve maliyet etkin)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Kalite (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Hafif katman, yukarıdaki Modeller tablosunda yapılandırılmış hızlı modeli kullanır (varsayılan: Haiku / Flash). Parçalar için tam sayfa modu kadar çeviri doğruluğu gerekiyorsa Kalite\'ye geçin.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'AI\'nin her hızlı çeviri için üretebileceği maksimum token sayısı. Varsayılan: 2.000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Giriş alanından kabul edilen maksimum karakter sayısı. Varsayılan: 8.000.','Content Generator'=>'İçerik Üreteci','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'AI İçerik Üreteci özelliği için token bütçesi ve giriş limitlerini kontrol eder. Alanları boş bırakmak, yerleşik varsayılanları kullanır.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Her üretim çalışması için AI\'nin üretebileceği maksimum token sayısı. Tam makaleler kesiliyorsa artırın. Varsayılan: 8.192.','Max hints characters'=>'İpucu karakterleri için maksimum sınır','Maximum characters read from the Hints field. Default: 2 000.'=>'İpucu alanından okunan maksimum karakter sayısı. Varsayılan: 2.000.','Max context characters'=>'Maksimum bağlam karakterleri','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'İpucu sağlanmadığında, AI\'ye iletilen mevcut gönderi içeriğinin maksimum karakter sayısı. Varsayılan: 6.000.','Maintenance'=>'Bakım','Language Overrides'=>'Dil Üzerinden Değişiklikleri','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Üçüncü taraf eklenti dizelerini geçersiz kılmak için derlenmiş .mo dosyalarını yükleyin — örneğin, "oda" yerine "daire" kullanan özel VikBooking çevirisi. Dosyalar WordPress adlandırma kurallarına uygun olmalı: {textdomain}-{locale}.mo (örneğin, vikbooking-ca.mo). Yükleme klasöründe saklanır ve eklenti güncellemelerine dayanır.','Override file uploaded successfully.'=>'Geçersiz kılma dosyası başarıyla yüklendi.','Override file deleted.'=>'Geçersiz kılma dosyası silindi.','No file was selected.'=>'Hiç dosya seçilmedi.','Only .mo files are accepted.'=>'Sadece .mo dosyaları kabul edilir.','The upload failed — please try again.'=>'Yükleme başarısız oldu — lütfen tekrar deneyin.','Could not save the file. Check that the uploads folder is writable.'=>'Dosya kaydedilemedi. Yükleme klasörünün yazılabilir olup olmadığını kontrol edin.','Invalid filename.'=>'Geçersiz dosya adı.','Security check failed — file path is not permitted.'=>'Güvenlik kontrolü başarısız — dosya yolu izin verilmedi.','An unknown error occurred.'=>'Bilinmeyen bir hata oluştu.','Text domain / locale'=>'Dil alanı / yerel ayar','Files'=>'Dosyalar','Size'=>'Boyut','Delete all files for this override (both .mo and .po)?'=>'Bu geçersiz kılma için tüm dosyaları silmek istiyor musunuz? (hem .mo hem de .po)','No override files uploaded yet.'=>'Henüz geçersiz kılma dosyası yüklenmedi.','Upload .mo file'=>'.mo dosyası yükle','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Sadece derlenmiş .mo dosyalarını kabul eder. Dosya adı {textdomain}-{locale}.mo kalıbını takip etmelidir. Aynı isimdeki bir dosya yüklemek onu değiştirecektir.','Upload Override'=>'Geçersiz kılma yükle','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Güvenli Depolamaya Kopyala','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate, özel çevirilerini wp-content/languages/loco/ dizininde saklar — bu konum, WP çekirdek güncellemesi, eklenti yeniden yüklemesi veya Loco Translate\'in kaldırılmasıyla sessizce silinebilir. Dosyaları buraya kopyalamak, bunları Lingua Forge i18n-overrides dizinine taşır ve bu dizin tüm bu olaylar sırasında kalıcıdır ve her istekte otomatik yüklenir.','File copied to safe storage successfully.'=>'Dosya güvenli depolamaya başarıyla kopyalandı.','Source file not found.'=>'Kaynak dosya bulunamadı.','Could not copy the file. Check that the uploads folder is writable.'=>'Dosya kopyalanamadı. Yükleme klasörünün yazılabilir olup olmadığını kontrol edin.','Invalid file reference.'=>'Geçersiz dosya referansı.','Type'=>'Tür','✓ In safe storage'=>'✓ Güvenli depolamada','Copy to safe storage'=>'Güvenli depolamaya kopyala','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Henüz özel Loco Translate dosyası bulunmuyor. Bir çeviri kaydettiğinizde burada görünürler.','AI Cache'=>'AI Önbelleği','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'Lingua Forge, AI tarafından oluşturulan çevirileri, meta açıklamaları, alıntıları ve içerikleri önbelleğe alır, böylece değişmeyen girişler ücretli API çağrısını yeniden tetiklemez. Önbelleğe alınan girişler, girişleri değiştiğinde otomatik olarak geçersiz kılınır. Veritabanı alanını geri kazanmak, sağlayıcı değiştirildikten veya istem prompt şablonları düzenlendikten sonra yeniden senkronize etmek veya önbellek sorunlarını gidermek için önbelleği manuel olarak temizleyin.','AI cache cleared. %d entry was removed.'=>'AI önbelleği temizlendi. %d giriş kaldırıldı.' . "\0" . 'AI önbelleği temizlendi. %d giriş kaldırıldı.','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Tüm önbelleğe alınmış AI sonuçlarını temizlesin mi? Gelecekteki istekler, önbellek yeniden oluşturulana kadar yeni API çağrılarını tetikleyecektir.','Clear AI Cache'=>'AI Önbelleğini Temizle','Debug Files'=>'Hata Ayıklama Dosyaları','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Hata ayıklama günlüğü etkinleştirildiğinde (aşağıdaki anahtar veya wp-config.php\'de LINGUAFORGE_AI_DEBUG tanımlanarak), Çeviri ve FSE şablon çeviri özellikleri sorun giderme için ham AI istemlerini ve yanıtlarını diske yazar. Bu bölümü, çıktıyı izlemek ve ihtiyacınız olanı aldıktan sonra temizlemek için kullanın — dosyalar büyük sayfalarda hızla büyüyebilir. Hedef dizini linguaforge_debug_dir filtresi aracılığıyla yapılandırın.','Debug files cleared. %d file was removed.'=>'Hata ayıklama dosyaları temizlendi. %d dosya kaldırıldı.' . "\0" . 'Hata ayıklama dosyaları temizlendi. %d dosya kaldırıldı.','Debug logging enabled.'=>'Hata ayıklama günlüğü etkinleştirildi.','Debug logging disabled.'=>'Hata ayıklama günlüğü devre dışı bırakıldı.','Debug logging'=>'Hata ayıklama günlüğü','Write AI prompts and responses to disk for troubleshooting'=>'Sorun giderme için AI istemlerini ve yanıtlarını diske yazın','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php\'deki LINGUAFORGE_AI_DEBUG sabiti tarafından ZORUNLU olarak AÇILDI. Bu anahtarı kaldırın, böylece buradan bu anahtarı kontrol edebilirsiniz.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php\'deki LINGUAFORGE_AI_DEBUG sabiti tarafından ZORUNLU olarak KAPATILDI. Bu anahtarı kaldırın, böylece buradan bu anahtarı kontrol edebilirsiniz.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Dosyalar aşağıdaki dizine kaydedilir. Çeviri sorunlarını teşhis etmek için kullanışlıdır — ihtiyacınız olanı aldıktan sonra kapatın, böylece dosyalar birikmez. Ayrıca wp-config.php\'den `define( \'LINGUAFORGE_AI_DEBUG\', true );` ile zorlayabilirsiniz, bu da anahtarı geçersiz kılar.','Currently:'=>'Şu anda:','✓ Enabled'=>'✓ Etkin','✗ Disabled'=>'✗ Devre Dışı','Directory'=>'Dizin','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Hata ayıklama çıktısını gizli olmayan bir konuma yönlendirmek için linguaforge_debug_dir filtresi ile kullanın.','.txt file(s) in the directory'=>'.txt dosyası(ları) dizinde','Save Debug Setting'=>'Hata ayıklama Ayarını Kaydet','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Hata ayıklama dizinindeki tüm .txt dosyalarını silmek istiyor musunuz? Dizin kendisi kalacak, böylece gelecekteki hata ayıklama yazıları düzgün şekilde kaydedilir.','Clear Debug Files'=>'Hata ayıklama Dosyalarını Temizle','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'İleti blokları arasında paylaşılan çeviri önbelleği. Ayarlar → Davranış bölümünde etkinleştir veya devre dışı bırak. Aşağıdaki istatistikler şu anda önbelleğe alınanları gösterir; temizleme, her blokun bir sonraki istekte yeniden çevrilmesini sağlar (model yükseltmeleri veya veritabanı alanını kurtarmak için kullanışlıdır).','Translation Memory cleared. %d cached block was removed.'=>'Çeviri Belleği temizlendi. %d önbelleğe alınmış blok kaldırıldı.' . "\0" . 'Çeviri Belleği temizlendi. %d önbelleğe alınmış blok kaldırıldı.','Status'=>'Durum','— toggle in Settings → Behavior.'=>'— Ayarlar → Davranış\'taki anahtar.','Cached blocks'=>'Önbelleğe alınmış bloklar','Cumulative cache hits'=>'Kümülatif önbellek erişimleri','(avg %.1f hits/block)'=>'(ortalama %.1f erişim/blok)','Oldest entry'=>'En eski giriş','Newest entry'=>'En yeni giriş','Approximate size'=>'Yaklaşık boyut','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Tüm Çeviri Belleğini temizle? Gelecekteki çeviriler önbelleği yeniden oluşturacaktır.','Clear Translation Memory'=>'Çeviri Belleğini Temizle','Uninstall Behaviour'=>'Kaldırma Davranışı','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Bir yönetici eklentiyi Kaldırmak için Eklentiler → Yüklü Eklentiler → Sil\'den sildiğinde ne olacağını kontrol eder. Eklenti ayarları ve AI önbellekleri her zaman kaldırılır. Dil atamaları ve çeviri ilişkileri varsayılan olarak korunur, böylece yanlışlıkla kaldırma veya yeniden yükleme kaldığı yerden devam edebilir.','Uninstall setting saved.'=>'Kaldırma ayarı kaydedildi.','Delete content data on uninstall'=>'Kaldırma sırasında içerik verilerini sil','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Ayrıca dil atamalarını, çeviri ilişkilerini, meta açıklamaları, sözlüğü ve Çeviri Belleğini kaldırırken, eklenti kaldırılır.','Warning:'=>'Uyarı:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'İşaretlenirse, eklentiyi kaldırmak, bu sitedeki tüm dil atamalarını, çeviri ilişkilerini, meta açıklamaları, sayfa ön ayarlarını, AI sözlüğünü ve Çeviri Belleğini kalıcı olarak silecektir. Bu geri alınamaz. Çok dilli desteği tamamen kaldırmıyorsanız, işaretlemeyin.','Save Uninstall Setting'=>'Kaldırma Ayarını Kaydet','Router'=>'Yönlendirici','Primary language saved.'=>'Birincil dil kaydedildi.','Permalink rules flushed successfully.'=>'Kalıcı bağlantı kuralları başarıyla temizlendi.','Primary Language'=>'Birincil Dil','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Birincil dil, sitenizin kökünde her zaman sunulur — yol modunda URL öneki yok, alt alan adında dil alt alan adı yok. Diğer tüm diller, aşağıdaki URL yapı ayarına bağlı olarak ya /lang/ yol öneki (ör. example.com/de/) ya da dil alt alan adı (ör. de.example.com) kullanır.','Primary language'=>'Birincil dil','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Birincil dili değiştirdikten sonra, URL yönlendirmesinin güncellenmesi için kalıcı bağlantıları (aşağıdaki bölüm) temizleyin.','URL structure'=>'URL yapısı','Path prefix — example.com/de/'=>'Yol öneki — example.com/tr/','Subdomain — de.example.com/'=>'Alt alan adı — tr.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Alt alan adı modu, web sunucunuzun tüm dil alt alan adlarını (ör. tr.example.com) bu WordPress kurulumuna yönlendirmesini gerektirir. Modları değiştirdikten sonra kalıcı bağlantı kurallarını temizleyin ve önbellekleri boşaltın. Ana URL\'nizde www varsa (ör. www.example.com), alt alan adlarının doğru şekilde oluşturulması için lf_base_domain filtresini kullanarak çıplak kök alan adını ayarlayın.','Browser language redirect'=>'Tarayıcı dili yönlendirmesi','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Ziyaretçileri, tarayıcının Accept-Language başlığına göre tercih ettikleri dile yönlendirin','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Etkinleştirildiğinde, ilk kez gelen ve dil çerezi veya URL\'de dil öneki olmayan ziyaretçiler, en yakın eşleşen dil sürümüne yönlendirilir. Yönlendirme, tarayıcının tercih ettiği dil aktif yönlendirici diller arasında değilse atlanır. Bir ziyaretçi, dil değiştirme aracını kullanarak bir dil seçtikten sonra, çerez öncelik kazanır ve tarayıcı başlığı tüm gelecekteki ziyaretlerde göz ardı edilir.','Save Router Settings'=>'Yönlendirici Ayarlarını Kaydet','Flush Permalinks'=>'Kalıcı Bağlantıları Temizle','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'WordPress yeniden yazma kurallarını yeniden oluşturur, böylece URL önekleri, dil özelindeki takma adlar ve arşiv yeniden yazmaları senkronize olur. Birincil dil değiştirildikten veya yeni dil desteği eklendikten sonra gereklidir.','Flush Permalink Rules'=>'Kalıcı Bağlantı Kurallarını Temizle','Active Languages'=>'Aktif Diller','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Yönlendirici tarafından şu anda bilinen diller (kurulu WordPress yerel paketleri ve birincil dilden türetilmiştir). Yönlendirme ve çeviri için daha fazla dil kullanılabilir hale getirmek üzere aşağıdaki bölümde ek dil paketleri yükleyin.','%d locale pack installed.'=>'%d yerel paket yüklü.' . "\0" . '%d yerel paket yüklü.','Install a Language'=>'Bir Dil Yükle','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'WordPress.org\'dan doğrudan bir WordPress çekirdek dil paketi indirip yükleyin. Yüklendikten sonra, yerel ayar URL yönlendirmesi ve AI çeviri akışı için kullanılabilir hale gelir. Mevcut diller listesi talep üzerine alınır — aşağıdaki düğmeye tıklayarak yükleyin.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Bu sunucuda dil yükleme devre dışı bırakılmıştır. wp-config.php dosyasında DISALLOW_FILE_MODS sabiti ayarlanmıştır. Dil paketlerini manuel olarak WP-CLI ile yükleyin: wp language core install de_DE','Load available languages'=>'Mevcut dilleri yükle','— select a language —'=>'— bir dil seçin —','Install'=>'Yükle','Language Setup'=>'Dil Kurulumu','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'İkincil dil yapılandırılmamış. Şablon iskeletini etkinleştirmek için yukarıdaki dil paketini yükleyin.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Bir dil seçin ve onun FSE şablonlarını, şablon parçalarını ve gezinme menülerini yönetin.','Forbidden'=>'Yasaklandı','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Bu sunucuda dil yükleme devre dışı bırakılmıştır (DISALLOW_FILE_MODS ayarlanmış).','Invalid locale code.'=>'Geçersiz yerel kod.','Language %s installed successfully.'=>'Dil %s başarıyla yüklendi.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Dil paketi yüklemesi başarısız oldu. Dil zaten yüklü olabilir, yerel kod yanlış olabilir veya sunucunuz dosya yazma işlemlerini engelliyor olabilir.','Navigations'=>'Gezintiler','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Gezinti çevirisi, aktif bir AI sağlayıcısı gerektirir. API Anahtarları sekmesinde bir API anahtarı yapılandırın.','Navigation'=>'Gezinti','Action'=>'Eylem','Re-translate'=>'Yeniden çevir','CPT Block Patterns'=>'CPT Blok Desenleri','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Özel gönderi türleri için kaydedilen blok desenleri. Bir dil varyantı üretmek için Çevir düğmesini kullanın. Çevirilen içerik burada kaydedilir ve blok düzenleyici Desen ekleyicisinden herhangi bir CPT gönderisine kopyalanabilir veya Senkronize Desen (Yeniden Kullanılabilir Blok) için başlangıç noktası olarak kullanılabilir.','Pattern'=>'Desen','Post Types'=>'Gönderi Türleri','✓ Translation saved'=>'✓ Çeviri kaydedildi','View'=>'Görüntüle','Template Parts'=>'Şablon Parçaları','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Temanın dil özelinde kopyaları. İskelet oluşturulduktan sonra, şablonlar dil özelinde parçayı referans gösterecek şekilde güncellenir.','Part'=>'Parça','Status / Actions'=>'Durum / İşlemler','Fix Links'=>'Bağlantıları Düzelt','Fix Nav'=>'Gezintiyi Düzelt','Create'=>'Oluştur','Templates'=>'Şablonlar','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Aktif temadan tohumlanan FSE şablonları. Site Düzenleyicisinde oluşturun ve özelleştirin.','Actions'=>'İşlemler','Fix Parts'=>'Parçaları Düzelt','Create missing'=>'Eksik olanı oluştur','Translate all'=>'Tümünü çevir','Fix all parts'=>'Tüm parçaları düzelt','Fix all links'=>'Tüm bağlantıları düzelt','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','Testing…'=>'Test ediliyor…','✓ Connection OK'=>'✓ Bağlantı OK','✗ Failed:'=>'✗ Başarısız:','No response from provider — check the error log for details.'=>'Sağlayıcıdan yanıt alınamadı — detaylar için hata günlüğünü kontrol edin.','Network error — could not reach the WordPress AJAX endpoint.'=>'Ağ hatası — WordPress AJAX uç noktasına ulaşılamadı.','Loading…'=>'Yükleniyor…','Installing…'=>'Yükleniyor…','✓ Language installed.'=>'✓ Dil yüklendi.','✗ Error:'=>'✗ Hata:','Creating…'=>'Oluşturuluyor…','✓ All templates created.'=>'✓ Tüm şablonlar oluşturuldu.','Some templates could not be created.'=>'Bazı şablonlar oluşturulamadı.','✓ All parts created.'=>'✓ Tüm parçalar oluşturuldu.','Some parts could not be created.'=>'Bazı parçalar oluşturulamadı.','✓ All translated.'=>'✓ Tüm çeviriler yapıldı.','Some translations failed.'=>'Bazı çeviriler başarısız oldu.','Review carefully — links and slugs not updated.'=>'Dikkatlice incele — bağlantılar ve slug\'lar güncellenmedi.','Fixing…'=>'Düzenleniyor…','✓ Links fixed.'=>'✓ Bağlantılar düzeltildi.','Some link fixes failed.'=>'Bazı bağlantı düzeltmeleri başarısız oldu.','✓ Parts fixed.'=>'✓ Parçalar düzeltildi.','Some part fixes failed.'=>'Bazı parça düzeltmeleri başarısız oldu.','✓ Nav refs fixed.'=>'✓ Navigasyon referansları düzeltildi.','Some nav ref fixes failed.'=>'Bazı navigasyon referansı düzeltmeleri başarısız oldu.','✓ Pattern translated.'=>'✓ Desen çevrildi.','Pattern translation failed.'=>'Desen çevirisi başarısız oldu.','Hide'=>'Gizle','Built-in preset instructions:'=>'Yerleşik ön ayar talimatları:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Yerleşik talimat yok — her AI özelliği kendi ayarlanmış varsayılanlarını kullanır. Aşağıdaki Özel istem alanını doldurarak kendi site genelinde kurallarınızı ekleyin.','Settings'=>'Ayarlar','You do not have permission to manage these settings.'=>'Bu ayarları yönetme izniniz yok.','Lingua Forge — Settings'=>'Lingua Forge — Ayarlar','Settings saved.'=>'Ayarlar kaydedildi.','Save Settings'=>'Ayarları Kaydet','Standard'=>'Standart','Technical / Scientific'=>'Teknik / Bilimsel','Legal / Compliance'=>'Yasal / Uyumluluk','Creative / Marketing'=>'Yaratıcı / Pazarlama','Full Article'=>'Tam Makale','Introduction only'=>'Sadece Giriş','Structured Outline'=>'Yapılandırılmış Taslak','Generate Content'=>'İçerik Oluştur','Hints'=>'İpuçları','Key points, ideas, or structure to build from…'=>'Anahtar noktalar, fikirler veya yapı...','Tone'=>'Ton','Output'=>'Çıktı','Generate Excerpt'=>'Özet Oluştur','Generate Meta Description'=>'Meta Açıklaması Oluştur','Translate Content'=>'İçeriği Çevir','Mode'=>'Mod','Full post'=>'Tam gönderi','Translate chunk'=>'Parçayı çevir','Target Language'=>'Hedef Dil','Text to translate'=>'Çevrilecek metin','Paste a footnote, sentence, or any snippet here…'=>'Buraya bir dipnot, cümle veya herhangi bir parçayı yapıştırın…','Also generate meta description'=>'Ayrıca meta açıklaması oluştur','Translated Names'=>'Çevirilen İsimler','Name displayed in this language. Leave empty to use the source name.'=>'Bu dilde görüntülenen isim. Kaynak ismi kullanmak için boş bırakın.','Too many AI requests. Please retry in %d seconds.'=>'Çok fazla AI isteği. Lütfen %d saniye içinde tekrar deneyin.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Günlük AI kotası aşıldı (%1$d istek). UTC %2$s\'de sıfırlanır.','View Lingua Forge details'=>'Lingua Forge detaylarını görüntüle','View details'=>'Detayları görüntüle','Visit plugin site'=>'Eklenti sitesini ziyaret et','%d language not yet linked'=>'%d dil henüz bağlantılı değil' . "\0" . '%d dil henüz bağlantılı değil','This is the source page. Footnotes are edited directly in the block editor.'=>'Bu kaynak sayfa. Dipnotlar doğrudan blok düzenleyicide düzenlenir.','No source page linked yet.'=>'Henüz kaynak sayfa bağlantısı yok.','The source page has no footnotes.'=>'Kaynak sayfada dipnot yok.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Bu dipnotlar kaynak sayfadan gelir ve burada sadece referans olarak gösterilir. Bunları blok düzenleyici kullanarak bu sayfaya ekleyin.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d yerelleştirilmiş şablon(lar) &#8220;%2$s&#8221; temasından veritabanında korunuyor, ancak şu anda etkin değil. Bu temayı yeniden etkinleştirirseniz, tekrar aktif hale gelirler. Çevirilerinizi yeni temaya taşımak için, <strong>Ayarlar → Lingua Forge → Yönlendirici → FSE iskeleti</strong> aracılığıyla yeniden oluşturun.','Scanning posts for broken language links…'=>'Kırık dil bağlantıları için gönderileri tarıyor…','Re-scanning…'=>'Tekrar tarama…','Scan failed: '=>'Tarama başarısız: ','unknown error'=>'bilinmeyen hata','Scan request failed. Please try again.'=>'Tarama isteği başarısız oldu. Lütfen tekrar deneyin.','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ <strong>{lang}</strong> gönderisi bulunamadı. Tüm çevrilmiş gönderilerin Dil meta kutusunda <strong>{lang}</strong> olarak ayarlandığından emin olun.','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ <strong>{lang}</strong> için kırık bağlantı veya şablon uyuşmazlığı bulunmadı. <strong>{scanned}</strong> gönderi ve sayfa tarandı — tüm kontroller geçti. Şablon parçası bağlantıları (başlık, altbilgi, yan menü) burada dahil değildir — bunları ayrı kontrol etmek için Şablon Parçalarını Düzelt düğmesini kullanın.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> otomatik düzeltilebilir bağlantı','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> manuel inceleme gerektiren bağlantı','and'=>'ve','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'<strong>{total}</strong> içindeki <strong>{parts}</strong> parça bulundu. <strong>{scanned}</strong> taranan gönderi için.','Post'=>'Gönderi','Links'=>'Bağlantılar','link(s)'=>'bağlantı','Fix'=>'Düzenle','✅ Fixed ({n})'=>'✅ Düzeltildi ({n})','⚠ No changes — re-scan?'=>'⚠ Değişiklik yok — tekrar tara?','⚠ No changes'=>'⚠ Değişiklik yok','❌ Failed'=>'❌ Başarısız','Done — {done} of {total} post(s) fixed.'=>'Tamamlandı — {done} gönderi düzeltildi, toplam {total}.','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} değiştirilmesi gereken bağlantı yok — araştırmak için tekrar tara)','Fixing {n} / {total}…'=>'{n} / {total} düzeltiliyor…','URL could not be mapped to a post — check the link target exists'=>'URL bir gönderiye eşlenemedi — bağlantı hedefinin var olup olmadığını kontrol edin','No {lang} translation registered (TRID missing)'=>'{lang} çevirisi kaydedilmedi (TRID eksik)','Translation found but permalink could not be generated'=>'Çeviri bulundu ancak kalıcı bağlantı oluşturulamadı','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> eski yol(lar)','📍 Stale path (page moved)'=>'📍 Eski yol (sayfa taşındı)','{n} stale path(s)'=>'{n} eski yol(lar)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> şablon sorunu(ları)','📄 Wrong template'=>'📄 Yanlış şablon','Expected: {expected}'=>'Beklenen: {expected}','Current: {current}'=>'Mevcut: {current}','Template "{expected}" does not exist — create it in the Site Editor first.'=>'"{expected}" şablonu mevcut değil — önce Site Düzenleyicisi\'nde oluşturun.','Fix Template'=>'Şablonu Düzelt','✅ Template fixed'=>'✅ Şablon düzeltildi','Internal Link Fixer'=>'İç Bağlantı Düzeltici','Fix All'=>'Tümünü Düzelt','Re-scan'=>'Yeniden Tara','Language Switcher'=>'Dil Değiştirici','Displays the Lingua Forge language switcher.'=>'Lingua Forge dil değiştiricisini gösterir.','Language'=>'Dil','Display'=>'Görüntüleme','Language label'=>'Dil etiketi','Icon only'=>'Sadece simge','Icon + label'=>'Simge + etiket','Dropdown direction'=>'Açılır menü yönü','Down'=>'Aşağı','Up'=>'Yukarı','You do not have permission to read this post.'=>'Bu gönderiyi okuma izniniz yok.','Post not found.'=>'Gönderi bulunamadı.','Limit results to pages in the given Lingua Forge language code.'=>'Sonuçları verilen Lingua Forge dil kodundaki sayfalara sınırla.','Meta Description'=>'Meta Açıklaması','Using custom meta description.'=>'Özel meta açıklaması kullanılıyor.','Prefilled from excerpt. Edit to override.'=>'Alıntıdan önceden dolduruldu. Üzerine yazmak için düzenle.','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'120–160 karakter hedefleyin. Boş bırakın, alıntı yedek kullanılsın.','↺ Refreshing…'=>'↺ Yenileme…','Review translation before applying'=>'Uygulamadan önce çeviriyi gözden geçirin','Current title'=>'Mevcut başlık','Translated title'=>'Çevirilmiş başlık','Current content (will be overwritten)'=>'Mevcut içerik ( üzerine yazılacak)','Translated content'=>'Çevirilmiş içerik','Footnotes payload (advanced)'=>'Dipnotlar yükü (ileri düzey)','Generated meta description'=>'Oluşturulan meta açıklaması','Saved to the meta description field when you apply.'=>'Uyguladığınızda meta açıklama alanına kaydedilir.','Cancel'=>'İptal','Apply translation'=>'Çeviriyi uygula','Generated Content'=>'Oluşturulan İçerik','Refine further:'=>'Daha fazla iyileştir:','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Taslağı geliştirmek için talimatlar